// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the system time.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter starts full and refills at rate tokens per second, up to burst.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	rate     float64 // tokens per second
	burst    float64
	clock    Clock
}

// ErrInvalidConfig is returned by New for non-positive rate or burst.
var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be > 0")

// New returns a Limiter allowing burst events instantly, refilling at rate
// tokens per second. Events are measured against the provided clock.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = RealClock()
	}
	return &Limiter{
		tokens: float64(burst),
		last:   clock.Now(),
		rate:   rate,
		burst:  float64(burst),
		clock:  clock,
	}, nil
}

// Allow reports whether one token is available at the current time.
func (l *Limiter) Allow() bool { return l.AllowN(time.Time{}, 1) }

// AllowN reports whether n tokens are available at time now. If now is the
// zero time, the limiter's clock is used. It consumes the tokens if allowed.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if now.IsZero() {
		now = l.clock.Now()
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the number of tokens currently available (for diagnostics).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
