// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock reports the current time. It is injectable for testing.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created with NewLimiter; the zero value is not usable.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	capacity float64
	rate     float64 // tokens per second
	clock    Clock
}

var (
	ErrNonPositiveRate     = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveCapacity = errors.New("ratelimit: capacity must be > 0")
	ErrNilClock            = errors.New("ratelimit: clock must not be nil")
)

// NewLimiter returns a Limiter that refills at rate tokens per second up to
// capacity tokens, starting full. clock may be nil, in which case the system
// clock is used.
func NewLimiter(rate, capacity float64, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if capacity <= 0 {
		return nil, ErrNonPositiveCapacity
	}
	if clock == nil {
		clock = systemClock{}
	}
	return &Limiter{
		tokens:   capacity,
		last:     clock.Now(),
		capacity: capacity,
		rate:     rate,
		clock:    clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available at time now, consuming them
// if so. It never blocks.
func (l *Limiter) AllowN(n float64) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}
	if l.tokens < n {
		return false
	}
	l.tokens -= n
	return true
}

// Tokens returns the number of tokens currently available.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
